 91→        roomClients.delete(client);
 92→        if (roomClients.size === 0) {
 93→          rooms.delete(roomId);
 94→        }
 95→      }
 96→
 97→      broadcast(roomId, 'playerDisconnected', {
 98→        userId: user.id,
 99→        username: user.username
100→      });
101→    });
102→
103→    // Handle errors
104→    ws.on('error', (err) => {
105→      console.error(`WebSocket error for user ${user.id} in room ${roomId}:`, err.message);
106→    });
107→  });
108→
109→  // Broadcast to all clients in a room, optionally excluding a user
110→  function broadcast(roomId, event, data, excludeUserId) {
111→    const roomClients = rooms.get(roomId);
112→    if (!roomClients) return;
113→
114→    const message = JSON.stringify({ event, data });
115→
116→    for (const client of roomClients) {
