193→  // GET /api/rooms — list user's active rooms
194→  const findUserRooms = db.prepare(`
195→    SELECT r.*, gs.current_turn, gs.move_history
196→    FROM rooms r
197→    JOIN game_states gs ON gs.room_id = r.id
198→    WHERE (r.white_user_id = ? OR r.black_user_id = ?)
199→    AND r.status IN ('waiting', 'playing')
200→    ORDER BY r.updated_at DESC
