209→      const blackUser = r.black_user_id ? findUserById.get(r.black_user_id) : null;
210→      const moveHistory = r.move_history ? JSON.parse(r.move_history) : [];
211→
212→      return {
213→        roomId: r.id,
214→        inviteCode: r.invite_code,
215→        status: r.status,
216→        white: whiteUser ? whiteUser.username : null,
217→        black: blackUser ? blackUser.username : null,
218→        myColor: r.white_user_id === userId ? 'white' : 'black',
219→        currentTurn: r.current_turn,
