228→  // GET /api/rooms/:id — get room and game state
229→  router.get('/:id', (req, res) => {
230→    const roomId = parseInt(req.params.id);
231→    if (isNaN(roomId)) {
232→      return res.status(400).json({ error: 'Invalid room ID' });
233→    }
234→
235→    const room = findRoomById.get(roomId);
236→    if (!room) {
237→      return res.status(404).json({ error: 'Room not found' });
238→    }
239→
240→    const gsRow = findGameState.get(roomId);
241→    if (!gsRow) {
242→      return res.status(404).json({ error: 'Game state not found' });
243→    }
244→
245→    const gameState = deserializeGameState(gsRow);
246→    const fen = boardToFEN(gameState);
247→    const legalMoves = room.status === 'playing' ? getLegalMoves(gameState) : [];
248→
249→    // Determine caller's color
250→    let myColor = null;
251→    if (req.user.id === room.white_user_id) myColor = 'white';
252→    else if (req.user.id === room.black_user_id) myColor = 'black';
253→
254→    // Get player names
255→    const whiteUser = room.white_user_id ? findUserById.get(room.white_user_id) : null;
256→    const blackUser = room.black_user_id ? findUserById.get(room.black_user_id) : null;
257→
258→    res.json({
259→      roomId: room.id,
260→      inviteCode: room.invite_code,
261→      status: room.status,
262→      isStockfish: !!room.is_stockfish,
263→      stockfishLevel: room.stockfish_level,
264→      result: room.result,
265→      white: whiteUser ? whiteUser.username : null,
266→      black: blackUser ? blackUser.username : null,
267→      myColor,
268→      fen,
269→      currentTurn: gameState.currentTurn,
270→      moveHistory: gameState.moveHistory,
271→      legalMoves,
272→      board: gameState.board
273→    });
274→  });
275→
276→  // POST /api/rooms/:id/move — submit a move
277→  router.post('/:id/move', (req, res) => {
278→    const roomId = parseInt(req.params.id);
279→    if (isNaN(roomId)) {
280→      return res.status(400).json({ error: 'Invalid room ID' });
281→    }
282→
283→    const { move } = req.body;
284→    if (!move || typeof move !== 'string') {
285→      return res.status(400).json({ error: 'move is required (UCI format, e.g. "e2e4")' });
286→    }
287→
288→    const parsed = parseMove(move);
289→    if (!parsed) {
290→      return res.status(400).json({ error: 'Invalid move format. Use UCI notation (e.g. "e2e4", "e7e8q")' });
291→    }
292→
293→    // Use a transaction to prevent race conditions
294→    const submitMove = db.transaction(() => {
295→      const room = findRoomById.get(roomId);
296→      if (!room) {
297→        return { status: 404, body: { error: 'Room not found' } };
298→      }
299→
300→      if (room.status !== 'playing') {
301→        return { status: 400, body: { error: 'Game is not in progress' } };
302→      }
303→
304→      // Verify it's this player's turn
305→      const gsRow = findGameState.get(roomId);
306→      const gameState = deserializeGameState(gsRow);
307→
308→      let expectedUserId;
309→      if (gameState.currentTurn === 'white') {
310→        expectedUserId = room.white_user_id;
311→      } else {
312→        expectedUserId = room.black_user_id;
313→      }
314→
315→      if (req.user.id !== expectedUserId) {
316→        return { status: 403, body: { error: 'Not your turn' } };
317→      }
318→
319→      // Check move legality
320→      const legality = isMoveLegal(gameState, parsed.from, parsed.to, parsed.promotion);
321→
322→      if (!legality.legal) {
323→        // Track consecutive illegal moves
324→        const key = getIllegalKey(roomId, req.user.id);
325→        const count = (illegalMoveCounters.get(key) || 0) + 1;
326→        illegalMoveCounters.set(key, count);
327→
328→        if (count >= 3) {
329→          // Forfeit the game
330→          const loser = gameState.currentTurn;
331→          const result = loser === 'white' ? '0-1' : '1-0';
332→          updateRoomResult.run(result, roomId);
333→          illegalMoveCounters.delete(key);
334→
335→          broadcast(roomId, 'gameOver', { result, reason: 'illegal_move_forfeit' });
336→
337→          return {
338→            status: 400,
339→            body: {
340→              error: legality.reason,
341→              forfeit: true,
342→              result,
343→              reason: 'Too many consecutive illegal moves (3)'
344→            }
345→          };
346→        }
347→
348→        const legalMoves = getLegalMoves(gameState);
349→        return {
350→          status: 400,
351→          body: {
352→            error: legality.reason,
353→            illegalMoveCount: count,
354→            legalMoves
355→          }
356→        };
357→      }
358→
359→      // Reset illegal move counter on legal move
360→      const key = getIllegalKey(roomId, req.user.id);
361→      illegalMoveCounters.delete(key);
362→
363→      // Apply the move
364→      const newGameState = applyMove(gameState, parsed.from, parsed.to, parsed.promotion);
365→
366→      // Check game result
367→      const gameResult = getGameResult(newGameState);
368→
369→      // Persist to SQLite
370→      const s = serializeGameState(newGameState);
371→      updateGameState.run(s.board, s.current_turn, s.move_history, s.en_passant_target, s.moved_pieces, s.half_move_clock, s.position_history, roomId);
372→
373→      if (gameResult.over) {
374→        updateRoomResult.run(gameResult.result, roomId);
375→      }
376→
377→      const fen = boardToFEN(newGameState);
378→
379→      const newLegalMoves = gameResult.over ? [] : getLegalMoves(newGameState);
380→
381→      return {
382→        status: 200,
383→        body: {
384→          ok: true,
385→          fen,
386→          move: move,
387→          board: newGameState.board,
388→          currentTurn: newGameState.currentTurn,
389→          moveHistory: newGameState.moveHistory,
390→          legalMoves: newLegalMoves,
391→          gameOver: gameResult.over,
392→          result: gameResult.over ? gameResult.result : undefined,
393→          reason: gameResult.over ? gameResult.reason : undefined
394→        },
395→        newGameState,
396→        gameResult,
397→        room
398→      };
399→    });
400→
401→    const txResult = submitMove();
402→    res.status(txResult.status).json(txResult.body);
403→
404→    // Post-transaction side effects
405→    if (txResult.status === 200) {
406→      // Broadcast move with full state so opponent doesn't need to re-fetch
407→      // Reuse legalMoves already computed in the transaction
408→      broadcast(roomId, 'move', {
409→        move,
410→        fen: txResult.body.fen,
411→        board: txResult.newGameState.board,
412→        currentTurn: txResult.newGameState.currentTurn,
413→        moveHistory: txResult.newGameState.moveHistory,
414→        legalMoves: txResult.body.legalMoves
415→      }, req.user.id);
416→
417→      if (txResult.gameResult.over) {
418→        broadcast(roomId, 'gameOver', {
419→          result: txResult.gameResult.result,
420→          reason: txResult.gameResult.reason
421→        });
422→      }
423→
424→      // If AvE and now Stockfish's turn, trigger async Stockfish move
425→      if (!txResult.gameResult.over && txResult.room.is_stockfish) {
426→        const sfUserId = getOrCreateStockfishUser();
427→        const nextTurn = txResult.newGameState.currentTurn;
428→        const nextUserId = nextTurn === 'white' ? txResult.room.white_user_id : txResult.room.black_user_id;
429→        if (nextUserId === sfUserId) {
430→          triggerStockfishMove(roomId);
431→        }
432→      }
433→    }
434→  });
435→
436→  // Async Stockfish move
437→  function triggerStockfishMove(roomId) {
438→    setTimeout(async () => {
439→      try {
440→        const sfPlayer = getStockfishPlayer();
441→        if (!sfPlayer) return;
442→
443→        const room = findRoomById.get(roomId);
444→        if (!room || room.status !== 'playing') return;
445→
446→        const gsRow = findGameState.get(roomId);
447→        const gameState = deserializeGameState(gsRow);
448→        const fen = boardToFEN(gameState);
449→
450→        const bestMove = await sfPlayer.getBestMove(fen, room.stockfish_level);
451→        if (!bestMove) return;
452→
453→        const moveStr = bestMove.from + bestMove.to + (bestMove.promotion || '');
454→
455→        // Apply Stockfish's move within a transaction
456→        const sfSubmit = db.transaction(() => {
457→          // Re-read to avoid stale state
458→          const freshGsRow = findGameState.get(roomId);
459→          const freshGameState = deserializeGameState(freshGsRow);
460→
461→          const parsed = parseMove(moveStr);
462→          if (!parsed) return null;
463→
464→          const legality = isMoveLegal(freshGameState, parsed.from, parsed.to, parsed.promotion);
465→          if (!legality.legal) {
466→            console.error(`Stockfish made illegal move: ${moveStr} — ${legality.reason}`);
467→            return null;
468→          }
469→
470→          const newGameState = applyMove(freshGameState, parsed.from, parsed.to, parsed.promotion);
471→          const gameResult = getGameResult(newGameState);
472→
473→          const s = serializeGameState(newGameState);
474→          updateGameState.run(s.board, s.current_turn, s.move_history, s.en_passant_target, s.moved_pieces, s.half_move_clock, s.position_history, roomId);
475→
476→          if (gameResult.over) {
477→            updateRoomResult.run(gameResult.result, roomId);
478→          }
479→
480→          return { newGameState, gameResult, moveStr };
481→        });
482→
483→        const result = sfSubmit();
484→        if (!result) return;
485→
486→        const newFen = boardToFEN(result.newGameState);
487→
488→        broadcast(roomId, 'move', {
489→          move: result.moveStr,
490→          fen: newFen,
491→          currentTurn: result.newGameState.currentTurn,
492→          moveHistory: result.newGameState.moveHistory
493→        });
494→
495→        if (result.gameResult.over) {
496→          broadcast(roomId, 'gameOver', {
497→            result: result.gameResult.result,
498→            reason: result.gameResult.reason
499→          });
500→        }
501→      } catch (err) {
502→        console.error('Stockfish move error:', err);
503→      }
504→    }, 100); // Small delay to let the HTTP response complete first
505→  }
506→
507→  return router;
508→}
509→
510→module.exports = { createRoomsRouter };
