  1→const express = require('express');
  2→const cors = require('cors');
  3→const http = require('http');
  4→const rateLimit = require('express-rate-limit');
  5→const { createDb } = require('./db');
  6→const { authMiddleware } = require('./middleware/auth');
  7→const { createAuthRouter } = require('./routes/auth');
  8→const { createRoomsRouter } = require('./routes/rooms');
  9→const { setupWebSocket } = require('./ws');
 10→const { createStockfishPlayer } = require('./chess/stockfishPlayer');
 11→
 12→const PORT = process.env.PORT || 3001;
 13→
 14→async function main() {
 15→  // Initialize database
 16→  const db = createDb();
 17→
 18→  // Initialize Stockfish (awaited so engine is ready before accepting requests)
 19→  let stockfishPlayer = await createStockfishPlayer();
 20→
 21→  // Create Express app
 22→  const app = express();
 23→
 24→  // Middleware
 25→  app.use(express.json());
 26→  const corsOrigins = process.env.CORS_ORIGINS
 27→    ? process.env.CORS_ORIGINS.split(',')
 28→    : [/^http:\/\/localhost:\d+$/, /^http:\/\/127\.0\.0\.1:\d+$/];
 29→  app.use(cors({
 30→    origin: corsOrigins,
 31→    credentials: true
 32→  }));
 33→
 34→  // Request logging
 35→  app.use((req, res, next) => {
 36→    const start = Date.now();
 37→    res.on('finish', () => {
 38→      const duration = Date.now() - start;
 39→      console.log(`${req.method} ${req.originalUrl} ${res.statusCode} ${duration}ms`);
 40→    });
 41→    next();
 42→  });
 43→
 44→  // Rate limiters
 45→  const isTest = process.env.NODE_ENV === 'test';
 46→
 47→  const signupLimiter = rateLimit({
 48→    windowMs: 60 * 1000, // 1 minute
 49→    max: 5,
 50→    standardHeaders: true,
 51→    legacyHeaders: false,
 52→    skip: () => isTest,
 53→    message: { error: 'Too many signup attempts. Try again in a minute.' }
 54→  });
 55→
 56→  const moveLimiter = rateLimit({
 57→    windowMs: 60 * 1000, // 1 minute
 58→    max: 60,
 59→    keyGenerator: (req) => req.user ? `user:${req.user.id}` : req.ip,
 60→    standardHeaders: true,
 61→    legacyHeaders: false,
 62→    skip: () => isTest,
 63→    message: { error: 'Too many moves. Slow down.' }
 64→  });
 65→
 66→  // Create HTTP server
 67→  const server = http.createServer(app);
 68→
 69→  // Setup WebSocket
 70→  const { broadcast } = setupWebSocket(server, db);
 71→
 72→  // Auth middleware instance
 73→  const auth = authMiddleware(db);
 74→
 75→  // Mount routes
 76→  app.use('/api/auth', signupLimiter, createAuthRouter(db));
 77→
 78→  const roomsRouter = createRoomsRouter(db, {
 79→    broadcast,
 80→    getStockfishPlayer: () => stockfishPlayer
 81→  });
 82→  app.use('/api/rooms', auth, roomsRouter);
 83→
 84→  // Apply move-specific rate limiter to move endpoint
 85→  app.use('/api/rooms/:id/move', moveLimiter);
 86→
 87→  // Health check
 88→  app.get('/api/health', (req, res) => {
 89→    res.json({
 90→      status: 'ok',
 91→      stockfish: !!stockfishPlayer
 92→    });
 93→  });
 94→
 95→  // Room expiry: every 5 minutes, delete stale waiting rooms
 96→  // Delete game_states first (child FK), then rooms (parent)
 97→  const findStaleRooms = db.prepare(`
 98→    SELECT id FROM rooms
 99→    WHERE status = 'waiting'
100→    AND created_at < datetime('now', '-15 minutes')
101→  `);
102→  const deleteGameStateByRoom = db.prepare('DELETE FROM game_states WHERE room_id = ?');
103→  const deleteRoomById = db.prepare('DELETE FROM rooms WHERE id = ?');
104→
105→  const expireStaleRooms = db.transaction(() => {
106→    const stale = findStaleRooms.all();
107→    for (const row of stale) {
108→      deleteGameStateByRoom.run(row.id);
109→      deleteRoomById.run(row.id);
110→    }
111→    return stale.length;
112→  });
113→
114→  setInterval(() => {
115→    const count = expireStaleRooms();
116→    if (count > 0) {
117→      console.log(`Expired ${count} stale waiting room(s)`);
118→    }
119→  }, 5 * 60 * 1000);
120→
121→  // Start server
122→  server.listen(PORT, () => {
123→    console.log(`Chess server listening on http://localhost:${PORT}`);
124→    console.log(`WebSocket available at ws://localhost:${PORT}/api/rooms/:id/ws?token=xxx`);
125→  });
126→
127→  // Graceful shutdown
128→  process.on('SIGINT', () => {
129→    console.log('\nShutting down...');
130→    if (stockfishPlayer) stockfishPlayer.terminate();
131→    db.close();
132→    server.close();
133→    process.exit(0);
134→  });
135→}
136→
137→main().catch(err => {
138→  console.error('Failed to start server:', err);
139→  process.exit(1);
140→});
141→

  1→const { WebSocketServer } = require('ws');
  2→const url = require('url');
  3→
  4→function setupWebSocket(server, db) {
  5→  const wss = new WebSocketServer({ noServer: true });
  6→
  7→  // Track clients per room: Map<roomId, Set<{ ws, userId, username, role }>>
  8→  const rooms = new Map();
  9→
 10→  const findUserByToken = db.prepare('SELECT id, username FROM users WHERE token = ?');
 11→  const findRoom = db.prepare('SELECT * FROM rooms WHERE id = ?');
 12→
 13→  // Handle HTTP upgrade
 14→  server.on('upgrade', (request, socket, head) => {
 15→    const parsed = url.parse(request.url, true);
 16→    const pathname = parsed.pathname;
 17→
 18→    // Match /api/rooms/:id/ws
 19→    const match = pathname.match(/^\/api\/rooms\/(\d+)\/ws$/);
 20→    if (!match) {
 21→      socket.destroy();
 22→      return;
 23→    }
 24→
 25→    const roomId = parseInt(match[1]);
 26→    const token = parsed.query.token;
 27→
 28→    if (!token) {
 29→      socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
 30→      socket.destroy();
 31→      return;
 32→    }
 33→
 34→    const user = findUserByToken.get(token);
 35→    if (!user) {
 36→      socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
 37→      socket.destroy();
 38→      return;
 39→    }
 40→
 41→    const room = findRoom.get(roomId);
 42→    if (!room) {
 43→      socket.write('HTTP/1.1 404 Not Found\r\n\r\n');
 44→      socket.destroy();
 45→      return;
 46→    }
 47→
 48→    // Determine role
 49→    let role = 'spectator';
 50→    if (user.id === room.white_user_id || user.id === room.black_user_id) {
 51→      role = 'player';
 52→    }
 53→
 54→    wss.handleUpgrade(request, socket, head, (ws) => {
 55→      wss.emit('connection', ws, { roomId, user, role });
 56→    });
 57→  });
 58→
 59→  // Handle new connections
 60→  wss.on('connection', (ws, { roomId, user, role }) => {
 61→    // Add to room tracking
 62→    if (!rooms.has(roomId)) {
 63→      rooms.set(roomId, new Set());
 64→    }
 65→
 66→    const client = { ws, userId: user.id, username: user.username, role };
 67→    rooms.get(roomId).add(client);
 68→
 69→    // Send joined confirmation to the new client
 70→    ws.send(JSON.stringify({
 71→      event: 'joined',
 72→      data: {
 73→        roomId,
 74→        userId: user.id,
 75→        username: user.username,
 76→        role
 77→      }
 78→    }));
 79→
 80→    // Notify others in the room
 81→    broadcast(roomId, 'playerConnected', {
 82→      userId: user.id,
 83→      username: user.username,
 84→      role
 85→    }, user.id);
 86→
 87→    // Handle disconnect
 88→    ws.on('close', () => {
 89→      const roomClients = rooms.get(roomId);
 90→      if (roomClients) {
 91→        roomClients.delete(client);
 92→        if (roomClients.size === 0) {
