**The move endpoint is a masterclass in transaction safety. Key structure:**

```javascript
router.post('/:id/move', (req, res) => {
  // 1. Parse and validate input
  const roomId = parseInt(req.params.id);
  if (isNaN(roomId)) return res.status(400).json({ error: '...' });

  // 2. Create transaction function
  const submitMove = db.transaction(() => {
    // Fetch current state
    const room = findRoomById.get(roomId);
    if (!room) return { status: 404, body: { error: '...' } };

    if (room.status !== 'playing') {
      return { status: 400, body: { error: 'Game is not in progress' } };
    }

    // Verify authorization (must be your turn)
    const gsRow = findGameState.get(roomId);
    const gameState = deserializeGameState(gsRow);
    let expectedUserId = gameState.currentTurn === 'white' 
      ? room.white_user_id 
      : room.black_user_id;

    if (req.user.id !== expectedUserId) {
      return { status: 403, body: { error: 'Not your turn' } };
    }

    // 3. Do business logic (apply move, check game result)
    // 4. Update database
    // 5. Return { status, body, extraData }

    return {
      status: 200,
      body: { ok: true, ... },
      extraData: { ... }  // passed outside transaction
    };
  });

  // 6. Execute transaction
  const txResult = submitMove();
  res.status(txResult.status).json(txResult.body);

  // 7. Post-transaction side effects (broadcast, async actions)
  if (txResult.status === 200) {
    broadcast(...);
    // Handle Stockfish if needed
  }
});
```

