      resignedColor: isWhite ? 'white' : 'black'
    };
  });

  const txResult = submitResign();
  res.status(txResult.status).json(txResult.body);

  if (txResult.status === 200) {
    broadcast(roomId, 'gameOver', {
      result: txResult.result,
      reason: 'resignation'
    });
  }
});

